+pub(crate) fn tmp_compute_leading_run(reg: &RegexType) -> Option<usize> {
+    if std::env::var_os("TMP_NO_RUNSKIP").is_some() {
+        return None;
+    }
+    if reg.needs_capture_tracking
+        || reg.extp.as_ref().is_some_and(|e| e.callout_num != 0)
+        || (reg.anchor & ANCR_BEGIN_POSITION) != 0
+    {
+        return None;
+    }
+    use OpCode::*;
+    if reg.ops.iter().any(|op| {
+        matches!(
+            op.opcode,
+            CheckPosition
+                | BackRef1
+                | BackRef2
+                | BackRefN
+                | BackRefNIc
+                | BackRefMulti
+                | BackRefMultiIc
+                | BackRefWithLevel
+                | BackRefWithLevelIc
+                | BackRefCheck
+                | BackRefCheckWithLevel
+                | Call
+                | CalloutContents
+                | CalloutName
+                | SaveVal
+                | UpdateVar
+        )
+    }) {
+        return None;
+    }
+    let mut pc = 0;
+    while pc < reg.ops.len() && matches!(reg.ops[pc].opcode, MemStart | MemStartPush | Mark) {
+        pc += 1;
+    }
+    let head = reg.ops.get(pc)?;
+    let star = reg.ops.get(pc + 1)?;
+    let same = match (head.opcode, star.opcode, &head.payload, &star.payload) {
+        (Word, WordStar, ..) | (WordAscii, WordAsciiStar, ..) | (WordAscii, WordAsciiStarPeekNext, ..) => true,
+        (CClass, CClassStar, OperationPayload::CClass { bsp: a, .. }, OperationPayload::CClass { bsp: b, .. }) => a == b,
+        (CClass, CClassStarPeekNext, OperationPayload::CClass { bsp: a, .. }, OperationPayload::CClassStarPeekNext { bsp: b, .. }) => a == b,
+        (CClassMix, CClassMixStar, OperationPayload::CClassMix { bsp: a, mb: m }, OperationPayload::CClassMix { bsp: b, mb: n }) => a == b && m == n,
+        (CClassMb, CClassMbStar, OperationPayload::CClassMb { mb: m }, OperationPayload::CClassMb { mb: n }) => m == n,
+        _ => false,
+    };
+    same.then_some(pc)
+}
