+/// End of the class run starting at `s` (s itself if `s` is not a member).
+pub(crate) fn tmp_run_end(reg: &RegexType, pc: usize, text: &[u8], end: usize, mut s: usize) -> usize {
+    let op = &reg.ops[pc];
+    while s < end {
+        let byte = text[s];
+        let len = enclen(reg.enc, text, s);
+        let next = s + len;
+        if next > end {
+            break;
+        }
+        let member = match (&op.opcode, &op.payload) {
+            (OpCode::Word, _) => is_word_char_at(reg.enc, text, s, end),
+            (OpCode::WordAscii, _) => is_word_ascii(byte),
+            (_, OperationPayload::CClass { bsp, .. }) => len == 1 && bitset_at(bsp, byte as usize),
+            (_, OperationPayload::CClassMb { mb }) => {
+                len > 1 && is_in_code_range(mb, reg.enc.mbc_to_code(&text[s..], end - s))
+            }
+            (_, OperationPayload::CClassMix { bsp, mb }) => {
+                if byte < 0x80 || len == 1 {
+                    bitset_at(bsp, byte as usize)
+                } else {
+                    let c = reg.enc.mbc_to_code(&text[s..], end - s);
+                    is_in_code_range(mb, c) || (c < 256 && bitset_at(bsp, c as usize))
+                }
+            }
+            _ => false,
+        };
+        if !member {
+            break;
+        }
+        s = next;
+    }
+    s
+}
