+/// Prototype: `[capture/atomic] C+ LITERAL...` where the optimizer's exact
+/// string is that literal (unbounded distance) and its first byte is not in
+/// C. Every match starts in the C-run right before a literal occurrence, and
+/// by the run-subset argument only the run's first position needs an attempt.
+pub(crate) fn tmp_compute_rev_run(reg: &RegexType) -> Option<usize> {
+    if std::env::var_os("TMP_NO_REVRUN").is_some() {
+        return None;
+    }
+    let pc = tmp_compute_leading_run(reg)?;
+    if reg.optimize != OptimizeType::StrFast || reg.dist_max != INFINITE_LEN || reg.exact.is_empty() {
+        return None;
+    }
+    let mut next = pc + 2;
+    if matches!(reg.ops.get(next)?.opcode, OpCode::CutToMark) {
+        next += 1;
+    }
+    let lit: &[u8] = match (&reg.ops.get(next)?.opcode, &reg.ops.get(next)?.payload) {
+        (OpCode::Str1 | OpCode::Str2 | OpCode::Str3 | OpCode::Str4 | OpCode::Str5, OperationPayload::Exact { s }) => {
+            let n = match reg.ops[next].opcode {
+                OpCode::Str1 => 1,
+                OpCode::Str2 => 2,
+                OpCode::Str3 => 3,
+                OpCode::Str4 => 4,
+                _ => 5,
+            };
+            &s[..n]
+        }
+        _ => return None,
+    };
+    if !reg.exact.starts_with(lit) && !lit.starts_with(&reg.exact) {
+        return None;
+    }
+    // The literal's first byte must end every run.
+    let probe = [reg.exact[0]];
+    if tmp_run_end(reg, pc, &probe, 1, 0) != 0 || reg.exact[0] >= 0x80 {
+        return None;
+    }
+    Some(pc)
+}
