+#[allow(clippy::too_many_arguments)]
+pub(crate) fn tmp_rev_run_search(
+    reg: &RegexType,
+    pc: usize,
+    str_data: &[u8],
+    end: usize,
+    mut s: usize,
+    cur_range: usize,
+    data_range: usize,
+    msa: &mut MatchArg,
+) -> Option<(i32, Option<OnigRegion>)> {
+    let finder = memchr::memmem::Finder::new(&reg.exact);
+    loop {
+        let k = s + finder.find(&str_data[s..end])?;
+        // scan back over the run
+        let mut r = k;
+        while r > s {
+            let mut h = r - 1;
+            while h > s && (str_data[h] & 0xC0) == 0x80 && r - h < 4 {
+                h -= 1;
+            }
+            if tmp_run_end(reg, pc, str_data, end, h) >= r {
+                r = h;
+            } else {
+                break;
+            }
+        }
+        if r < k && r <= cur_range {
+            msa.best_len = ONIG_MISMATCH;
+            msa.best_s = 0;
+            let res = match_at(reg, str_data, end, data_range, r, msa);
+            if res != ONIG_MISMATCH {
+                if res < 0 {
+                    return Some((res, msa.region.take()));
+                }
+                return Some((r as i32, msa.region.take()));
+            }
+        }
+        if k >= cur_range {
+            return Some((ONIG_MISMATCH, msa.region.take()));
+        }
+        s = k + 1;
+    }
+}
