+trait TmpPipe {
+    fn pipe_fix(self, msa: &mut MatchArg) -> (i32, Option<OnigRegion>);
+}
+impl TmpPipe for (i32, Option<OnigRegion>) {
+    fn pipe_fix(self, msa: &mut MatchArg) -> (i32, Option<OnigRegion>) {
+        match self {
+            (r, None) => (r, msa.region.take()),
+            x => x,
+        }
+    }
+}
